    "summary": "Algoritmo de programa√ß√£o que modula dinamicamente a densidade e encurta pontos em curvas fechadas para evitar ac√∫mulo e quebra de linha.",
    "origin": "Do grego autos (por si mesmo) e do latim spatium (intervalo, dist√¢ncia). Termo cunhado na d√©cada de 1980 pelos pioneiros de algoritmos CAD de bordado (Wilcom / Pulse) para descrever a modula√ß√£o matem√°tica aut√¥noma do passo de ponto em vetores curvos.",
